function winnerGameDate(date:string,language:"es"|"en"){
  if(language==="es")return date;
  const months:Record<string,string>={ene:"Jan",feb:"Feb",mar:"Mar",abr:"Apr",may:"May",jun:"Jun",jul:"Jul",ago:"Aug",sep:"Sep",oct:"Oct",nov:"Nov",dic:"Dec"};
  return date.replace(/\b(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)\b/gi,(month)=>months[month.toLowerCase()]||month);
}

