function roundedBox(ctx:CanvasRenderingContext2D,x:number,y:number,w:number,h:number,r:number,fill:string,stroke:string|null,width:number){ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
function drawWrappedText(ctx:CanvasRenderingContext2D,text:string,x:number,y:number,maxWidth:number,lineHeight:number){const words=text.split(" ");let line="",lineY=y;for(const word of words){const test=`${line}${word} `;if(line&&ctx.measureText(test).width>maxWidth){ctx.fillText(line.trim(),x,lineY);line=`${word} `;lineY+=lineHeight;}else line=test;}if(line)ctx.fillText(line.trim(),x,lineY);}
function countWrappedTextLines(ctx:CanvasRenderingContext2D,text:string,maxWidth:number){const words=text.split(" ");let line="",lines=1;for(const word of words){const test=`${line}${word} `;if(line&&ctx.measureText(test).width>maxWidth){lines+=1;line=`${word} `;}else line=test;}return lines;}
function fitCanvasText(ctx:CanvasRenderingContext2D,text:string,maxWidth:number){if(ctx.measureText(text).width<=maxWidth)return text;let value=text;while(value.length>1&&ctx.measureText(`${value}â€¦`).width>maxWidth)value=value.slice(0,-1);return `${value}â€¦`;}
function canvasFontToFit(ctx:CanvasRenderingContext2D,text:string,maxWidth:number,maxSize:number,font:string,minSize=14){let size=maxSize;ctx.font=`400 ${size}px ${font}`;while(size>minSize&&ctx.measureText(text).width>maxWidth){size-=1;ctx.font=`400 ${size}px ${font}`;}return size;}
function loadCanvasImage(src:string){return new Promise<HTMLImageElement>((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error("No se pudo cargar el logo"));image.src=src;});}
const TEAM_LOGO_SLUGS:Record<string,string>={"Denver Broncos":"den","Kansas City Chiefs":"kc","New York Giants":"nyg","Los Angeles Rams":"lar","Philadelphia Eagles":"phi","Chicago Bears":"chi","Atlanta Falcons":"atl","New Orleans Saints":"no","Buffalo Bills":"buf","Washington Commanders":"wsh","San Francisco 49ers":"sf","Dallas Cowboys":"dal","Seattle Seahawks":"sea","Minnesota Vikings":"min","Los Angeles Chargers":"lac","Baltimore Ravens":"bal","Cincinnati Bengals":"cin","Carolina Panthers":"car","Tampa Bay Buccaneers":"tb","Pittsburgh Steelers":"pit","Jacksonville Jaguars":"jax","New England Patriots":"ne","Detroit Lions":"det","Houston Texans":"hou","Green Bay Packers":"gb"};
function teamLogoSlug(team:string){return TEAM_LOGO_SLUGS[team.trim()]??"";}
function flyerFilename(type:FlyerType){return type==="winner-en"?"mnf-football-pool-2026-winner-en.png":type==="winner"?"ganador-quiniela-mnf-2026.png":type==="payment-en"?"mnf-football-pool-2026-payment.jpg":type==="payment"?"cobro-casillas-quiniela-mnf-2026.jpg":type==="report"?"avance-quiniela-mnf-2026.png":type==="schedule-en"?"mnf-football-pool-2026-games-en.png":type==="schedule"?"quiniela-mnf-2026-juegos.png":type==="board-en"?"mnf-football-pool-2026-en.png":"quiniela-mnf-2026.png";}
function downloadFlyer(blob:Blob,type:FlyerType="board"){const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=flyerFilename(type);link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function isOwned(square:Square,me:Member){ return Boolean(square.reservedByEmail) && square.reservedByEmail.toLowerCase()===me.email.toLowerCase(); }
function labelFor(status:Status){ return status==="available"?"Disponible":status==="reserved"?"Reservada":status==="paid"?"Pagada":"TesorerÃ­a"; }
function roleLabel(role:Role){ return role==="admin"?"Administrador":role==="treasury"?"TesorerÃ­a":"Usuario"; }
function roleIcon(role:Role){ return role==="admin"?"A":role==="treasury"?"T":"U"; }
function roleHelp(role:Role,boardLocked=false){ if(role==="admin")return "Puedes modificar cualquier dato, administrar accesos y configurar los nÃºmeros.";if(boardLocked)return role==="treasury"?"El tablero estÃ¡ cerrado. Puedes confirmar pagos y registrar las casillas recibidas en TesorerÃ­a.":"El tablero estÃ¡ cerrado. Puedes consultar las casillas, pero ya no reservarlas ni editarlas.";return role==="treasury"?"Puedes reservar casillas, confirmar pagos y registrar las casillas recibidas en TesorerÃ­a.":"Puedes reservar casillas disponibles y actualizar los datos de las que tÃº vendiste. TesorerÃ­a confirmarÃ¡ los pagos."; }
function initials(name:string){ return name.split(/\s+/).filter(Boolean).slice(0,2).map((part)=>part[0]).join("").toUpperCase(); }
function cleanDigits(value:string){ return value.replace(/\D/g,"").slice(0,10); }
function isDigitSet(value:string){ return value.length===10&&new Set(value).size===10&&[...value].every((digit)=>"0123456789".includes(digit)); }
function gameDateLabel(gameId:number,games:Game[],seasonName:string){const game=games[gameId-1];return game?`${game.date} ${seasonName}`:"";}
function formatPaymentDeadline(value:string,language:"es"|"en"){const [year,month,day]=value.split("-").map(Number);if(!year||!month||!day)return language==="es"?"fecha por definir":"date to be announced";return new Intl.DateTimeFormat(language==="es"?"es-MX":"en-US",{day:"numeric",month:"long",year:"numeric"}).format(new Date(year,month-1,day));}
function passwordMeetsPolicy(value:string){ return value.length>=8&&value.length<=128&&/[a-z]/.test(value)&&/[A-Z]/.test(value)&&/[0-9]/.test(value)&&/[^A-Za-z0-9]/.test(value); }
function activityIcon(action:string){ return action==="paid"?"$":action==="treasury"?"T":action==="reserved"?"R":action==="released"?"â†º":action.startsWith("game_result")?"J":action.startsWith("season_")?"T":"Â·"; }
function activityText(item:Activity){ if(item.action==="paid")return `marcÃ³ como pagada la casilla ${item.squareId}`;if(item.action==="treasury")return `registrÃ³ en TesorerÃ­a la casilla ${item.squareId}`;if(item.action==="reserved")return `reservÃ³ la casilla ${item.squareId} para ${item.details}`;if(item.action==="released")return `liberÃ³ la casilla ${item.squareId}`;if(item.action==="member_updated")return `actualizÃ³ el acceso de ${item.details}`;if(item.action==="member_removed")return `retirÃ³ el acceso de ${item.details}`;if(item.action==="numbers_updated")return "actualizÃ³ los nÃºmeros de juego";if(item.action==="game_result_updated")return `registrÃ³ el resultado: ${item.details}`;if(item.action==="game_result_cleared")return `eliminÃ³ el resultado del ${item.details}`;if(item.action==="game_results_cleared")return `eliminÃ³ todos los marcadores: ${item.details}`;if(item.action==="season_updated")return `actualizÃ³ la temporada: ${item.details}`;if(item.action==="season_activated")return `activÃ³ la nueva temporada: ${item.details}`;return `actualizÃ³ la casilla ${item.squareId}`; }
function formatNoteDate(value:string){ try{return new Intl.DateTimeFormat("es-MX",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(value));}catch{return value;} }
function formatDate(value:string){ try{return new Intl.DateTimeFormat("es-MX",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(value));}catch{return value;} }
